export interface FinalPlanLane {
  readonly description: string;
  readonly lane: string;
  readonly owns: readonly string[];
}

export interface FinalPlanStep {
  readonly expectedChanges: readonly string[];
  readonly goal: string;
  readonly id: string;
  readonly lane: string;
  readonly parallelSafeWith: readonly string[];
  readonly prerequisites: readonly string[];
  readonly readOnlyPaths: readonly string[];
  readonly researchSources: readonly string[];
  readonly testFiles: readonly string[];
  readonly title: string;
  readonly writeLock: readonly string[];
}

function step(
  id: string,
  lane: string,
  title: string,
  goal: string,
  prerequisites: readonly string[],
  writeLock: readonly string[],
  readOnlyPaths: readonly string[],
  expectedChanges: readonly string[],
  testFiles: readonly string[],
  researchSources: readonly string[] = ['AGENTS.md', 'plan_final/README.md'],
): FinalPlanStep {
  return Object.freeze({
    expectedChanges,
    goal,
    id,
    lane,
    parallelSafeWith: ['all lanes except steps sharing the write lock'],
    prerequisites,
    readOnlyPaths,
    researchSources,
    testFiles,
    title,
    writeLock,
  });
}

